  /// Section topic description for user context. Matches 6.1 requirement
  /// (5-250 characters).
  description String?

  /// Timestamp when section was created. Standard required field.
  created_at DateTime @db.Timestamptz

  /// Timestamp when section was last modified. Standard required field.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when section was soft-deleted. Standard optional field for
  /// audit.
