/// applied the ban. Each ban entry is linked to the banned user and the
/// administrator who initiated the ban, with soft delete support for audit
/// trails.
///
/// @namespace Bans
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model economic_political_discussion_board_bans {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Ban applies to a user.
  user_id String @db.Uuid

  /// Administrator who applied the ban.
  admin_user_id String @db.Uuid

  /// Reason for the ban as provided by the administrator.
  reason String

  /// Indicates if ban is currently active (true) or lifted (false).
  active Boolean

  /// Timestamp when ban was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when ban was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when ban was soft-deleted.
  deleted_at DateTime? @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  bannedUser economic_political_discussion_board_users @relation("economic_political_discussion_board_bans_of_user_id", fields: [user_id], references: [id], onDelete: Cascade)
  appliedBy economic_political_discussion_board_users @relation("economic_political_discussion_board_bans_of_admin_user_id", fields: [admin_user_id], references: [id], onDelete: Cascade)

  //----
  // INDEXES
  //----
  @@index([user_id])
  @@index([admin_user_id])
}

