        {
          data: {
            id: v4(),
            article_id: props.articleId,
            tag_id: tagRecord.id,
          },
        },
      );
    }
  }
  await MyGlobal.prisma.economic_political_discussion_board_articles.update({
    where: { id: props.articleId },
