}): Promise<IEconomicPoliticalDiscussionBoardSection> {
  const section =
    await MyGlobal.prisma.economic_political_discussion_board_sections.findUniqueOrThrow(
      {
        where: { id: props.id },
        select: {
          id: true,
          name: true,
          description: true,
